l"}]') WHERE 1
ON CONFLICT (anio, numero) DO UPDATE SET
  fecha_solgastos = excluded.fecha_solgastos, fecha_cotizacion = excluded.fecha_cotizacion,
  fecha_adjudicacion = excluded.fecha_adjudicacion, fecha_orden = excluded.fecha_orden, ordenes = excluded.ordenes,
  fecha_recepcion = excluded.fecha_recepcion, ultima_etapa = excluded.ultima_etapa, ultimo_estado = excluded.ultimo_estado,
  actualizado_en = excluded.actualizado_en;
INSERT OR IGNORE INTO suministros (anio, numero, estado, origen, secretaria, fuente, dependencia, fecha_carga, mes_inicio, meses_consumo, monto)
SELECT p.anio, p.numero, 'pendiente', 'rafam', COALESCE(
  (SELECT mj.secretaria FROM mapa_jurisdicciones mj WHERE mj.jurisdiccion = p.jurisdiccion),
  (SELECT md.secretaria FROM mapa_dependencias md WHERE md.jurisdiccion = p.jurisdiccion AND md.dependencia = p.dependencia)), p.fuente, p.dependencia, p.fecha, substr(p.fecha, 1, 7), 1, p.costo_total
FROM pedidos_rafam p WHERE p.anio = 2026 AND COALESCE(p.estado_rafam, '') <> 'Anulado';
UPDATE suministros AS s SET monto = p.costo_total, fuente = p.fuente, dependencia = p.dependencia,
  secretaria = COALESCE(s.secretaria, COALESCE(
  (SELECT mj.secretaria FROM mapa_jurisdicciones mj WHERE mj.jurisdiccion = p.jurisdiccion),
  (SELECT md.secretaria FROM mapa_dependencias md WHERE md.jurisdiccion = p.jurisdiccion AND md.dependencia = p.dependencia))), actualizado_en = datetime('now')
FROM pedidos_rafam p
WHERE p.anio = s.anio AND p.numero = s.numero AND s.anio = 2026 AND s.estado = 'pendiente' AND s.origen = 'rafam';
UPDATE suministros AS s SET estado = 'rechazado', motivo_rechazo = 'Anulado en RAFAM', resuelto_por = 'sync',
  resuelto_en = datetime('now'), actualizado_en = datetime('now')
FROM pedidos_rafam p
WHERE p.anio = s.anio AND p.numero = s.numero AND s.anio = 2026 AND s.estado = 'pendiente' AND p.estado_rafam = 'Anulado';
